∀ {randomness : ℕ → ℕ} {queries : ℕ} {run : (x : List Bool) → Fin (2 ^ randomness x.length) → PCP.QueryTree queries}
  {randomness_1 : ℕ → ℕ} {queries_1 : ℕ}
  {run_1 : (x : List Bool) → Fin (2 ^ randomness_1 x.length) → PCP.QueryTree queries_1},
  { randomness := randomness, queries := queries, run := run } =
      { randomness := randomness_1, queries := queries_1, run := run_1 } →
    randomness = randomness_1 ∧ queries = queries_1 ∧ run ≍ run_1

∀ {P : (List Bool → List Bool → Bool) → Prop} {L : PCP.Language} {witnessBound : Polynomial ℕ}
  {check : List Bool → List Bool → Bool} {check_polyTime : P check}
  {spec : ∀ (x : List Bool), L x ↔ ∃ w, w.length ≤ Polynomial.eval x.length witnessBound ∧ check x w = true}
  {witnessBound_1 : Polynomial ℕ} {check_1 : List Bool → List Bool → Bool} {check_polyTime_1 : P check_1}
  {spec_1 : ∀ (x : List Bool), L x ↔ ∃ w, w.length ≤ Polynomial.eval x.length witnessBound_1 ∧ check_1 x w = true},
  { witnessBound := witnessBound, check := check, check_polyTime := check_polyTime, spec := spec } =
      { witnessBound := witnessBound_1, check := check_1, check_polyTime := check_polyTime_1, spec := spec_1 } →
    witnessBound = witnessBound_1 ∧ check = check_1

